-- Clients shown on the town pages (/areas/<area>). Work done and years are read live from each
-- client's invoices; this table only says who is shown, under which name and in which town.
CREATE TABLE "WebsiteAreaClient" (
    "id" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "invoiceNames" TEXT[],
    "area" TEXT NOT NULL,
    "locality" TEXT NOT NULL DEFAULT '',
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "WebsiteAreaClient_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "WebsiteAreaClient_area_idx" ON "WebsiteAreaClient"("area");

-- The 69 clients the owner approved on 2026-10-21 from the invoice export, as on the live town pages.
-- Fixed ids and ON CONFLICT keep a re-run harmless.
ON CONFLICT ("id") DO NOTHING;
